 activatePractice(kind){this.practiceReturnState=this.state();this.practiceModel=createPractice(kind);this.screen='game';this.paused=false;this.needsResume=false;this.confirmation=null;this.frame();}
 startPractice(kind){this.action({type:'startPractice',kind});if(this.h.account().account?.run){this.confirmation={kind:'startPractice',practiceKind:kind};this.frame();return false;}this.activatePractice(kind);return true;}
 exitPractice(){this.action({type:'exitPractice'});this.practiceModel=null;this.stateFallback=this.practiceReturnState;this.screen='settings';this.paused=false;this.frame();}
