  const canvas=createCanvas(this.h.canvas.width,this.h.canvas.height),context=canvas.getContext('2d'),v=this.h.viewport,k=Math.min(v.w/L.width,(v.h-v.safe)/L.height),ox=(v.w-L.width*k)/2,oy=v.safe+(v.h-v.safe-L.height*k)/2;
  context.fillStyle='#0c131c';context.fillRect(0,0,canvas.width,canvas.height);context.setTransform(k*v.dpr,0,0,k*v.dpr,ox*v.dpr,oy*v.dpr);render(context,this.practiceModel.state,this.view());
